const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const todoqueElParaiso = ee.Geometry.Polygon(
    [[[-17.925464, 28.625899],
      [-17.915017, 28.618635],
      [-17.906159, 28.608320],
      [-17.907945, 28.599727],
      [-17.918931, 28.598687],
      [-17.929849, 28.607519],
      [-17.931750, 28.618035],
      [-17.925464, 28.625899]]]);

  const date1_start = '2021-05-01'; // Before eruption
  const date1_end = '2021-06-30';
  const date2_start = '2021-12-01'; // After eruption
  const date2_end = '2021-12-31';

  // 2. Data Acquisition & Pre-processing (Sentinel-2)
  // Function to mask clouds using the SCL band
  function maskS2clouds(image) {
    const SCL = image.select('SCL');
    // Clouds, cloud shadows, and cirrus are pixels with SCL values 3, 8, 9, 10, 11
    // Pixels with SCL values 0, 1, 2 (No Data, Saturated, Dark Area) are also masked
    // 4 = Vegetation, 5 = Not-vegetated, 6 = Water, 7 = Unclassified
    const cloudedPixels = SCL.eq(3).or(SCL.eq(8)).or(SCL.eq(9)).or(SCL.eq(10)).or(SCL.eq(11)).or(SCL.eq(0)).or(SCL.eq(1)).or(SCL.eq(2));
    return image.updateMask(cloudedPixels.not());
  }

  // Function to calculate NBR
  function calculateNBR(image) {
    return image.normalizedDifference(['B8', 'B12']).rename('NBR');
  }

  // Get Sentinel-2 L2A collection (surface reflectance)
  const collection = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
    .filterBounds(todoqueElParaiso);

  // Filter and process image for date 1 (before eruption)
  let col1 = collection.filterDate(date1_start, date1_end)
    .filter(ee.Filter.lt('CLOUDY_PIXEL_PERCENTAGE', 10))
    .map(maskS2clouds)
    .map(calculateNBR);

  if (col1.size().getInfo() === 0) {
    console.log("No images found for period 1 (before eruption).");
    console.log("C1");
    return;
  }
  const img1 = col1.median().clip(todoqueElParaiso);

  // Filter and process image for date 2 (after eruption)
  let col2 = collection.filterDate(date2_start, date2_end)
    .filter(ee.Filter.lt('CLOUDY_PIXEL_PERCENTAGE', 10))
    .map(maskS2clouds)
    .map(calculateNBR);

  if (col2.size().getInfo() === 0) {
    console.log("No images found for period 2 (after eruption).");
    console.log("C1");
    return;
  }
  const img2 = col2.median().clip(todoqueElParaiso);

  // Calculate NBR for both images
  const nbr1 = img1.select('NBR');
  const nbr2 = img2.select('NBR');

  // 3. Lava Flow Detection
  // Lava flows typically have very low NBR values, often negative.
  // We'll use a threshold to identify potential lava flow areas.
  // A threshold of NBR < -0.1 is often used for burn scars and also works for bare lava.
  const lavaThreshold = -0.1;

  const lava1 = nbr1.lt(lavaThreshold);
  const lava2 = nbr2.lt(lavaThreshold);

  // Mask out areas that were already lava-like in the first period,
  // to identify *new* lava flows.
  // However, for this specific question, it's about the total area of lava flow.
  // A simple way to determine 'increase' is to compare the lava area in the 'after' image
  // with the lava area in the 'before' image.
  // The area in the 'before' image should ideally be close to zero if the chosen AOI was vegetated.

  // 4. Calculate Area
  const scale = 10; // Sentinel-2 resolution
  const pixelArea = ee.Image.pixelArea().mask(lava1);

  const stats1 = lava1.multiply(pixelArea).reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: todoqueElParaiso,
    scale: scale,
    maxPixels: 1e9,
  });

  const area1_sqm = stats1.get('NBR').getInfo();

  const stats2 = lava2.multiply(ee.Image.pixelArea()).reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: todoqueElParaiso,
    scale: scale,
    maxPixels: 1e9,
  });

  const area2_sqm = stats2.get('NBR').getInfo();

  // Validate results
  if (area1_sqm === null || area2_sqm === null) {
    console.log("C3");
    return;
  }

  // Convert to hectares
  const area1_ha = area1_sqm / 10000;
  const area2_ha = area2_sqm / 10000;

  // Check valid pixels to avoid C2
  const count1 = img1.select('NBR').reduceRegion({
    reducer: ee.Reducer.count(), geometry: todoqueElParaiso, scale: scale, maxPixels: 1e9
  }).get('NBR').getInfo();
  const count2 = img2.select('NBR').reduceRegion({
    reducer: ee.Reducer.count(), geometry: todoqueElParaiso, scale: scale, maxPixels: 1e9
  }).get('NBR').getInfo();

  if (count1 === 0 || count2 === 0) {
    console.log("No valid pixels after masking for one or both periods.");
    console.log("C2");
    return;
  }

  const areaIncrease_ha = area2_ha - area1_ha;

  console.log(`Images for Period 1 (May-Jun 2021): ${col1.size().getInfo()}`);
  console.log(`Images for Period 2 (Dec 2021): ${col2.size().getInfo()}`);
  console.log(`Valid pixels Period 1: ${count1}`);
  console.log(`Valid pixels Period 2: ${count2}`);
  console.log(`Lava flow area (May-Jun 2021): ${area1_ha.toFixed(2)} ha`);
  console.log(`Lava flow area (Dec 2021): ${area2_ha.toFixed(2)} ha`);
  console.log(`Increase in lava flow area: ${areaIncrease_ha.toFixed(2)} ha`);

  // 5. Validation & Final Answer
  if (areaIncrease_ha > 0.0) { // Allowing for tiny fluctuations, require a meaningful increase.
    console.log("A"); // Yes
  } else {
    console.log("B"); // No
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
